  name: string;
  lessons: Lesson[];
}

export interface CognitiveLevel {
  know: number;
  understand: number;
  apply: number;
}

export interface MatrixRow {
  content: string;
  lessonName: string;
  part1: CognitiveLevel; // MCQ (18 total)
  part2: CognitiveLevel; // T/F (16 total)
  part3: CognitiveLevel; // Short Answer (6 total)
