import { Grade, Chapter, MatrixData, MatrixRow, CognitiveLevel } from '../types';

/**
 * Total Commands: 18 (Part 1) + 16 (Part 2) + 6 (Part 3) = 40
 * Target Ratios:
 * Know: 40% of 40 = 16
 * Understand: 30% of 40 = 12
 * Apply: 30% of 40 = 12
 * 
 * Distribution Strategy:
 * Part 1 (MCQ - 18): 12 Know, 6 Understand
 * Part 2 (T/F - 16): 4 Know, 6 Understand, 6 Apply
 * Part 3 (Short - 6): 6 Apply
 * 
 * Check:
 * Know: 12 + 4 = 16 (40%) - OK
 * Understand: 6 + 6 = 12 (30%) - OK
 * Apply: 6 + 6 = 12 (30%) - OK
 */

export const generateMatrix = (grade: Grade, chapter: Chapter): MatrixData => {
  const lessonCount = chapter.lessons.length;

  // Helper to distribute a total count across N bins as evenly as possible
  const distribute = (total: number, bins: number): number[] => {
    const base = Math.floor(total / bins);
    const remainder = total % bins;
    return Array.from({ length: bins }, (_, i) => base + (i < remainder ? 1 : 0));
  };

  // Distribution bins
  const p1_know = distribute(12, lessonCount);
  const p1_understand = distribute(6, lessonCount);

  const p2_know = distribute(4, lessonCount);
  const p2_understand = distribute(6, lessonCount);
  const p2_apply = distribute(6, lessonCount);

  const p3_apply = distribute(6, lessonCount);

  const rows: MatrixRow[] = chapter.lessons.map((lesson, idx) => {
    const rowP1 = { know: p1_know[idx], understand: p1_understand[idx], apply: 0 };
    const rowP2 = { know: p2_know[idx], understand: p2_understand[idx], apply: p2_apply[idx] };
    const rowP3 = { know: 0, understand: 0, apply: p3_apply[idx] };

    return {
      content: chapter.name,
      lessonName: lesson.name,
      part1: rowP1,
      part2: rowP2,
      part3: rowP3,
      total: (rowP1.know + rowP1.understand) + (rowP2.know + rowP2.understand + rowP2.apply) + rowP3.apply
    };
  });

  return {
    grade,
    chapter,
    rows,
    totals: {
      part1: { know: 12, understand: 6, apply: 0 },
      part2: { know: 4, understand: 6, apply: 6 },
      part3: { know: 0, understand: 0, apply: 6 },
      grandTotal: 40,
      ratio: { know: 16, understand: 12, apply: 12 }
    }
  };
};

import React, { useState, useCallback, useRef } from 'react';
import { CURRICULUM } from './constants';
import { Grade, Chapter, MatrixData } from './types';
import { generateMatrix } from './services/matrixService';
import MatrixDisplay from './components/MatrixDisplay';
import { Layout, Plus, Download, FileSpreadsheet, Image as ImageIcon, CheckCircle, ChevronRight, School } from 'lucide-react';
import * as XLSX from 'xlsx';
import html2canvas from 'html2canvas';

const App: React.FC = () => {
  const [activeGrade, setActiveGrade] = useState<Grade | null>(null);
  const [selectedChapter, setSelectedChapter] = useState<Chapter | null>(null);
  const [matrixData, setMatrixData] = useState<MatrixData | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  const handleGradeSelect = (grade: Grade) => {
    setActiveGrade(grade);
    setSelectedChapter(null);
  };

  const handleCreateNew = () => {
    setActiveGrade(null);
    setSelectedChapter(null);
    setMatrixData(null);
  };

  const handleGenerate = () => {
    if (!activeGrade || !selectedChapter) return;
    setIsGenerating(true);

    // Simulate slight delay for effect
    setTimeout(() => {
      const data = generateMatrix(activeGrade, selectedChapter);
      setMatrixData(data);
      setIsGenerating(false);
    }, 400);
  };

  const exportToExcel = () => {
    if (!matrixData) return;

    const wsData = [
      ['MA TRẬN ĐỀ KIỂM TRA HÓA HỌC'],
      [`LỚP ${matrixData.grade} - ${matrixData.chapter.name}`],
      [],
      ['TT', 'Nội dung', 'Đơn vị kiến thức', 'P1-Biết', 'P1-Hiểu', 'P1-VD', 'P2-Biết', 'P2-Hiểu', 'P2-VD', 'P3-Biết', 'P3-Hiểu', 'P3-VD', 'Tổng', 'Tỉ lệ'],
      ...matrixData.rows.map((row, idx) => [
        idx + 1,
        row.content,
        row.lessonName,
        row.part1.know, row.part1.understand, row.part1.apply,
        row.part2.know, row.part2.understand, row.part2.apply,
        row.part3.know, row.part3.understand, row.part3.apply,
        row.total,
        `${((row.total / 40) * 100).toFixed(1)}%`
      ]),
      ['', 'TỔNG CỘNG', '', 
        matrixData.totals.part1.know, matrixData.totals.part1.understand, matrixData.totals.part1.apply,
        matrixData.totals.part2.know, matrixData.totals.part2.understand, matrixData.totals.part2.apply,
        matrixData.totals.part3.know, matrixData.totals.part3.understand, matrixData.totals.part3.apply,
        matrixData.totals.grandTotal, '100%'
      ]
    ];

    const ws = XLSX.utils.aoa_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Matrix');
    XLSX.writeFile(wb, `Matrix_Chemistry_Grade${matrixData.grade}_${matrixData.chapter.id}.xlsx`);
  };

  const exportToImage = async () => {
    const element = document.getElementById('matrix-table-container');
    if (!element) return;

    const canvas = await html2canvas(element, { scale: 2 });
    const image = canvas.toDataURL('image/png', 1.0);
    const link = document.createElement('a');
    link.download = `Matrix_Chemistry_Grade${matrixData?.grade}.png`;
    link.href = image;
    link.click();
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-blue-700 text-white p-6 shadow-lg no-print">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <Layout className="w-10 h-10" />
            <div>
              <h1 className="text-2xl font-bold">Hệ Thống Lập Ma Trận Hóa Học</h1>
              <p className="text-blue-100 text-sm">Chương trình GDPT 2018 (KNTT - CD - CTST)</p>
            </div>
          </div>
          <button 
            onClick={handleCreateNew}
            className="bg-white text-blue-700 px-6 py-2 rounded-full font-bold shadow-md hover:bg-blue-50 transition-colors flex items-center gap-2"
          >
            <Plus className="w-5 h-5" /> TẠO MA TRẬN MỚI
          </button>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full p-6 space-y-8">
        {!matrixData && (
          <div className="bg-white rounded-xl shadow-md p-8 border border-blue-100 no-print">
            <h3 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
              <School className="text-blue-600" /> Chọn phạm vi nội dung kiến thức
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              {[10, 11, 12].map((g) => (
                <button
                  key={g}
                  onClick={() => handleGradeSelect(g as Grade)}
                  className={`p-6 rounded-xl border-2 transition-all text-left group ${
                    activeGrade === g 
                    ? 'border-blue-600 bg-blue-50' 
                    : 'border-gray-100 hover:border-blue-300'
                  }`}
                >
                  <span className={`text-3xl font-bold mb-2 block ${activeGrade === g ? 'text-blue-600' : 'text-gray-400 group-hover:text-blue-400'}`}>LỚP {g}</span>
                  <span className="text-sm text-gray-500">Môn Hóa học THPT</span>
                </button>
              ))}
            </div>

            {activeGrade && (
              <div className="animate-in fade-in slide-in-from-top-4 duration-300">
                <h4 className="font-semibold text-gray-700 mb-4 flex items-center gap-2">
                  <ChevronRight className="w-4 h-4" /> Danh sách chương Hóa học {activeGrade}
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-8 max-h-[400px] overflow-y-auto pr-2">
                  {CURRICULUM[activeGrade].map((chapter) => (
                    <button
                      key={chapter.id}
                      onClick={() => setSelectedChapter(chapter)}
                      className={`p-4 text-left rounded-lg border transition-all ${
                        selectedChapter?.id === chapter.id
                        ? 'bg-blue-600 text-white border-blue-600 shadow-md'
                        : 'bg-white text-gray-700 border-gray-200 hover:bg-gray-50'
                      }`}
                    >
                      {chapter.name}
                    </button>
                  ))}
                </div>

                <div className="flex justify-center">
                  <button
                    disabled={!selectedChapter || isGenerating}
                    onClick={handleGenerate}
                    className={`px-12 py-4 rounded-xl font-bold text-lg shadow-xl transition-all flex items-center gap-3 ${
                      !selectedChapter || isGenerating
                      ? 'bg-gray-300 cursor-not-allowed text-gray-500'
                      : 'bg-gradient-to-r from-blue-600 to-indigo-700 text-white hover:scale-105 active:scale-95'
                    }`}
                  >
                    {isGenerating ? 'ĐANG TẠO...' : 'BẮT ĐẦU TẠO MA TRẬN'}
                    {!isGenerating && <CheckCircle className="w-6 h-6" />}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {matrixData && (
          <div className="space-y-6">
            <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-blue-50 p-6 rounded-xl border border-blue-200 no-print">
              <div>
                <h3 className="text-lg font-bold text-blue-900">Ma trận đã được tạo thành công!</h3>
                <p className="text-blue-700 text-sm">Sử dụng các nút bên phải để tải xuống kết quả.</p>
              </div>
              <div className="flex flex-wrap gap-3">
                <button 
                  onClick={exportToExcel}
                  className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg font-bold hover:bg-emerald-700 shadow-sm transition-colors"
                >
                  <FileSpreadsheet className="w-5 h-5" /> TẢI FILE EXCEL (.xlsx)
                </button>
                <button 
                  onClick={exportToImage}
                  className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold hover:bg-indigo-700 shadow-sm transition-colors"
                >
                  <ImageIcon className="w-5 h-5" /> TẢI FILE ẢNH (.png)
                </button>
              </div>
            </div>

            <MatrixDisplay data={matrixData} />

            <div className="bg-white p-6 rounded-xl border shadow-sm no-print">
              <h4 className="font-bold text-gray-800 mb-4">Ghi chú về phân bổ:</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-gray-600">
                <p>• <b>Tỉ lệ nhận thức:</b> Biết (40%) - Hiểu (30%) - Vận dụng (30%).</p>
                <p>• <b>Hình thức:</b> 18 câu MCQ (4.5đ), 4 context Đúng/Sai (4.0đ), 6 câu SA (1.5đ).</p>
                <p>• <b>Phạm vi:</b> Đồng bộ kiến thức cốt lõi giữa 3 bộ sách giáo khoa mới nhất.</p>
                <p>• <b>Tính năng:</b> Tự động chia đều các lệnh hỏi dựa trên số lượng bài học trong chương.</p>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t p-6 mt-12 no-print">
        <div className="max-w-6xl mx-auto text-center text-gray-500 text-sm">
          <p>© 2024 Hệ thống Lập Ma Trận Đề Kiểm Tra Hóa Học. Dành cho Giáo viên Việt Nam.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
