import React, { useState, useEffect } from 'react';
import { CURRICULUM } from './constants';
import { Grade, Chapter, MatrixData, Lesson } from './types';
import { generateMatrix } from './services/matrixService';
import MatrixDisplay from './components/MatrixDisplay';
import { Layout, Plus, Download, FileSpreadsheet, Image as ImageIcon, CheckCircle, ChevronRight, School, Trash2, Edit3, Save } from 'lucide-react';
import * as XLSX from 'xlsx';
import html2canvas from 'html2canvas';

const App: React.FC = () => {
  const [activeGrade, setActiveGrade] = useState<Grade | null>(null);
  const [selectedChapter, setSelectedChapter] = useState<Chapter | null>(null);
  const [editableLessons, setEditableLessons] = useState<Lesson[]>([]);
  const [newLessonName, setNewLessonName] = useState('');
  const [matrixData, setMatrixData] = useState<MatrixData | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  // Initialize editable lessons when a chapter is selected
  useEffect(() => {
    if (selectedChapter) {
      setEditableLessons([...selectedChapter.lessons]);
    } else {
      setEditableLessons([]);
    }
  }, [selectedChapter]);

  const handleGradeSelect = (grade: Grade) => {
    setActiveGrade(grade);
    setSelectedChapter(null);
    setMatrixData(null);
  };

  const handleCreateNew = () => {
    setActiveGrade(null);
    setSelectedChapter(null);
    setMatrixData(null);
    setEditableLessons([]);
  };

  const handleAddLesson = () => {
    if (!newLessonName.trim()) return;
    const newLesson: Lesson = {
      id: `custom_${Date.now()}`,
      name: newLessonName.trim()
    };
    setEditableLessons([...editableLessons, newLesson]);
    setNewLessonName('');
  };

  const handleRemoveLesson = (id: string) => {
    setEditableLessons(editableLessons.filter(l => l.id !== id));
  };

  const handleGenerate = () => {
    if (!activeGrade || !selectedChapter || editableLessons.length === 0) return;
    setIsGenerating(true);

    // Use the customized list of lessons for the matrix
    const customChapter: Chapter = {
      ...selectedChapter,
      lessons: editableLessons
    };

    setTimeout(() => {
      const data = generateMatrix(activeGrade, customChapter);
      setMatrixData(data);
      setIsGenerating(false);
    }, 400);
  };

  const exportToExcel = () => {
    if (!matrixData) return;

    const wsData = [
      ['MA TRẬN ĐỀ KIỂM TRA HÓA HỌC'],
      [`LỚP ${matrixData.grade} - ${matrixData.chapter.name}`],
      [],
      ['TT', 'Nội dung', 'Đơn vị kiến thức', 'P1-Biết', 'P1-Hiểu', 'P1-VD', 'P2-Biết', 'P2-Hiểu', 'P2-VD', 'P3-Biết', 'P3-Hiểu', 'P3-VD', 'Tổng', 'Tỉ lệ'],
      ...matrixData.rows.map((row, idx) => [
        idx + 1,
        row.content,
        row.lessonName,
        row.part1.know, row.part1.understand, row.part1.apply,
        row.part2.know, row.part2.understand, row.part2.apply,
        row.part3.know, row.part3.understand, row.part3.apply,
        row.total,
        `${((row.total / 40) * 100).toFixed(1)}%`
      ]),
      ['', 'TỔNG CỘNG', '', 
