export type Grade = 10 | 11 | 12;

export interface Lesson {
  id: string;
  name: string;
  subItems?: string[]; // New: Detailed content items
}

export interface Chapter {
  id: string;
  name: string;
  lessons: Lesson[];
}

export interface CognitiveLevel {
  know: number;
  understand: number;
  apply: number;
}

export interface MatrixRow {
  content: string;
  lessonName: string;
  detailName: string; // New: Specific sub-item name
  isFirstInLesson: boolean; // For rowSpan logic
  lessonRowCount: number; // For rowSpan logic
  part1: CognitiveLevel;
  part2: CognitiveLevel;
  part3: CognitiveLevel;
  total: number;
}

export interface MatrixData {
  grade: Grade;
  chapter: Chapter;
  rows: MatrixRow[];
  totals: {
    part1: CognitiveLevel;
    part2: CognitiveLevel;
    part3: CognitiveLevel;
    grandTotal: number;
    ratio: CognitiveLevel;
  };
}

import { Grade, Chapter, MatrixData, MatrixRow, CognitiveLevel } from '../types';

export const generateMatrix = (grade: Grade, chapter: Chapter): MatrixData => {
  // Create a flat list of all "units" to distribute questions over
  const flatUnits: { lessonId: string; lessonName: string; detailName: string }[] = [];

  chapter.lessons.forEach(lesson => {
    if (lesson.subItems && lesson.subItems.length > 0) {
      lesson.subItems.forEach(item => {
        flatUnits.push({ 
          lessonId: lesson.id, 
          lessonName: lesson.name, 
          detailName: item 
        });
      });
    } else {
      // If no sub-items, use the lesson name itself as the detail
      flatUnits.push({ 
        lessonId: lesson.id, 
        lessonName: lesson.name, 
        detailName: '(Toàn bộ nội dung)' 
      });
    }
  });

  const totalUnits = flatUnits.length;

  // Helper to distribute a total count across N bins as evenly as possible
  const distribute = (total: number, bins: number): number[] => {
    if (bins === 0) return [];
    const base = Math.floor(total / bins);
    const remainder = total % bins;
    return Array.from({ length: bins }, (_, i) => base + (i < remainder ? 1 : 0));
  };

  // Distribution bins based on flat units
  const p1_know = distribute(12, totalUnits);
  const p1_understand = distribute(6, totalUnits);

  const p2_know = distribute(4, totalUnits);
  const p2_understand = distribute(6, totalUnits);
  const p2_apply = distribute(6, totalUnits);

  const p3_apply = distribute(6, totalUnits);

  const rows: MatrixRow[] = flatUnits.map((unit, idx) => {
    const rowP1 = { know: p1_know[idx], understand: p1_understand[idx], apply: 0 };
    const rowP2 = { know: p2_know[idx], understand: p2_understand[idx], apply: p2_apply[idx] };
    const rowP3 = { know: 0, understand: 0, apply: p3_apply[idx] };

    // Calculate rowSpan helper data
    const lessonUnits = flatUnits.filter(u => u.lessonId === unit.lessonId);
    const isFirstInLesson = lessonUnits[0] === unit;

    return {
      content: chapter.name,
      lessonName: unit.lessonName,
      detailName: unit.detailName,
      isFirstInLesson,
      lessonRowCount: lessonUnits.length,
      part1: rowP1,
      part2: rowP2,
      part3: rowP3,
      total: (rowP1.know + rowP1.understand) + (rowP2.know + rowP2.understand + rowP2.apply) + rowP3.apply
    };
  });

  return {
    grade,
    chapter,
    rows,
    totals: {
      part1: { know: 12, understand: 6, apply: 0 },
      part2: { know: 4, understand: 6, apply: 6 },
      part3: { know: 0, understand: 0, apply: 6 },
      grandTotal: 40,
      ratio: { know: 16, understand: 12, apply: 12 }
    }
  };
};

