import { Grade, Chapter, MatrixData, MatrixRow, CognitiveLevel } from '../types';

export const generateMatrix = (grade: Grade, chapter: Chapter): MatrixData => {
  // Create a flat list of all "units" to distribute questions over
  const flatUnits: { lessonId: string; lessonName: string; detailName: string }[] = [];

  chapter.lessons.forEach(lesson => {
    if (lesson.subItems && lesson.subItems.length > 0) {
      lesson.subItems.forEach(item => {
        flatUnits.push({ 
          lessonId: lesson.id, 
          lessonName: lesson.name, 
          detailName: item 
        });
      });
    } else {
      flatUnits.push({ 
        lessonId: lesson.id, 
        lessonName: lesson.name, 
        detailName: '(Toàn bộ nội dung)' 
      });
    }
  });

  const totalUnits = flatUnits.length;

  const distribute = (total: number, bins: number): number[] => {
    if (bins === 0) return [];
    const base = Math.floor(total / bins);
    const remainder = total % bins;
    return Array.from({ length: bins }, (_, i) => base + (i < remainder ? 1 : 0));
  };

  const p1_know = distribute(12, totalUnits);
  const p1_understand = distribute(6, totalUnits);
  const p2_know = distribute(4, totalUnits);
  const p2_understand = distribute(6, totalUnits);
  const p2_apply = distribute(6, totalUnits);
  const p3_apply = distribute(6, totalUnits);

  const rows: MatrixRow[] = flatUnits.map((unit, idx) => {
    const rowP1 = { know: p1_know[idx], understand: p1_understand[idx], apply: 0 };
    const rowP2 = { know: p2_know[idx], understand: p2_understand[idx], apply: p2_apply[idx] };
    const rowP3 = { know: 0, understand: 0, apply: p3_apply[idx] };

    const lessonUnits = flatUnits.filter(u => u.lessonId === unit.lessonId);
    const lessonIdx = lessonUnits.indexOf(unit);
    const isFirstInLesson = lessonIdx === 0;
    const isLastInLesson = lessonIdx === lessonUnits.length - 1;

    return {
      content: chapter.name,
      lessonName: unit.lessonName,
      detailName: unit.detailName,
      isFirstInLesson,
      isLastInLesson,
      lessonRowCount: lessonUnits.length,
      part1: rowP1,
      part2: rowP2,
      part3: rowP3,
      total: (rowP1.know + rowP1.understand) + (rowP2.know + rowP2.understand + rowP2.apply) + rowP3.apply
    };
  });

  return {
    grade,
    chapter,
    rows,
    totals: {
      part1: { know: 12, understand: 6, apply: 0 },
      part2: { know: 4, understand: 6, apply: 6 },
      part3: { know: 0, understand: 0, apply: 6 },
      grandTotal: 40,
      ratio: { know: 16, understand: 12, apply: 12 }
    }
  };
};

import { Grade, Chapter, MatrixData, MatrixRow, CognitiveLevel } from '../types';

export const generateMatrix = (grade: Grade, chapter: Chapter): MatrixData => {
  const lessonCount = chapter.lessons.length;

  // Helper to distribute a total count across N bins as evenly as possible
  const distribute = (total: number, bins: number): number[] => {
    if (bins === 0) return [];
    const base = Math.floor(total / bins);
    const remainder = total % bins;
    return Array.from({ length: bins }, (_, i) => base + (i < remainder ? 1 : 0));
  };

  // 1. Distribute specific cognitive counts per part across Lessons (Knowledge Units)
  // Part 1 (MCQ - 18): 12 Know, 6 Understand
  const lessonP1K = distribute(12, lessonCount);
  const lessonP1U = distribute(6, lessonCount);

  // Part 2 (T/F - 16): 4 Know, 6 Understand, 6 Apply
  const lessonP2K = distribute(4, lessonCount);
  const lessonP2U = distribute(6, lessonCount);
  const lessonP2V = distribute(6, lessonCount);

  // Part 3 (SA - 6): 6 Apply
  const lessonP3V = distribute(6, lessonCount);

  const rows: MatrixRow[] = [];

  // 2. For each lesson, distribute its assigned quota into its sub-items
  chapter.lessons.forEach((lesson, lIdx) => {
    const subItems = (lesson.subItems && lesson.subItems.length > 0) 
      ? lesson.subItems 
      : ['(Toàn bộ nội dung)'];

    const subItemCount = subItems.length;

    // Distribute the lesson's share among its sub-items
    const s1k = distribute(lessonP1K[lIdx], subItemCount);
    const s1u = distribute(lessonP1U[lIdx], subItemCount);

    const s2k = distribute(lessonP2K[lIdx], subItemCount);
    const s2u = distribute(lessonP2U[lIdx], subItemCount);
    const s2v = distribute(lessonP2V[lIdx], subItemCount);

    const s3v = distribute(lessonP3V[lIdx], subItemCount);

    subItems.forEach((detailName, sIdx) => {
      const rowP1 = { know: s1k[sIdx], understand: s1u[sIdx], apply: 0 };
      const rowP2 = { know: s2k[sIdx], understand: s2u[sIdx], apply: s2v[sIdx] };
      const rowP3 = { know: 0, understand: 0, apply: s3v[sIdx] };

      rows.push({
        content: chapter.name,
        lessonName: lesson.name,
        detailName,
        isFirstInLesson: sIdx === 0,
        isLastInLesson: sIdx === subItemCount - 1,
        lessonRowCount: subItemCount,
        part1: rowP1,
        part2: rowP2,
        part3: rowP3,
        total: (rowP1.know + rowP1.understand) + (rowP2.know + rowP2.understand + rowP2.apply) + rowP3.apply
      });
    });
  });

  return {
    grade,
    chapter,
    rows,
    totals: {
      part1: { know: 12, understand: 6, apply: 0 },
      part2: { know: 4, understand: 6, apply: 6 },
      part3: { know: 0, understand: 0, apply: 6 },
      grandTotal: 40,
      ratio: { know: 16, understand: 12, apply: 12 }
    }
  };
};

import { Grade, Chapter, MatrixData, MatrixRow, CognitiveLevel } from '../types';

export const generateMatrix = (grade: Grade, chapter: Chapter): MatrixData => {
  const lessonCount = chapter.lessons.length;

  // Helper to distribute a total count across N bins as evenly as possible
  const distribute = (total: number, bins: number): number[] => {
    if (bins === 0) return [];
    const base = Math.floor(total / bins);
    const remainder = total % bins;
    return Array.from({ length: bins }, (_, i) => base + (i < remainder ? 1 : 0));
  };

  // 1. Distribute Chapter-level quota across Lessons (Knowledge Units)
  // Ensure roughly equal weight per unit (e.g. 33% each for 3 units)
  const lessonP1K = distribute(12, lessonCount);
  const lessonP1U = distribute(6, lessonCount);
  const lessonP2K = distribute(4, lessonCount);
  const lessonP2U = distribute(6, lessonCount);
  const lessonP2V = distribute(6, lessonCount);
  const lessonP3V = distribute(6, lessonCount);

  const rows: MatrixRow[] = [];

  // 2. Process each Lesson
  chapter.lessons.forEach((lesson, lIdx) => {
    const subItems = (lesson.subItems && lesson.subItems.length > 0) 
      ? lesson.subItems 
      : ['(Toàn bộ nội dung)'];

    const subItemCount = subItems.length;

    // Helper for Rotational Distribution within sub-items
    // This ensures that different types of questions (P1, P2, P3) start at different sub-items
    // spreading the coverage and minimizing empty items.
    const rotateDistribute = (count: number, items: number, offset: number): number[] => {
      const result = new Array(items).fill(0);
      for (let i = 0; i < count; i++) {
        result[(i + offset) % items]++;
      }
      return result;
    };

    // Use different offsets for each cognitive type to maximize coverage
    const s1k = rotateDistribute(lessonP1K[lIdx], subItemCount, 0);
    const s1u = rotateDistribute(lessonP1U[lIdx], subItemCount, 1);
    const s2k = rotateDistribute(lessonP2K[lIdx], subItemCount, 2);
    const s2u = rotateDistribute(lessonP2U[lIdx], subItemCount, 3);
    const s2v = rotateDistribute(lessonP2V[lIdx], subItemCount, 4);
    const s3v = rotateDistribute(lessonP3V[lIdx], subItemCount, 5);

    subItems.forEach((detailName, sIdx) => {
      const rowP1 = { know: s1k[sIdx], understand: s1u[sIdx], apply: 0 };
      const rowP2 = { know: s2k[sIdx], understand: s2u[sIdx], apply: s2v[sIdx] };
      const rowP3 = { know: 0, understand: 0, apply: s3v[sIdx] };

      rows.push({
        content: chapter.name,
        lessonName: lesson.name,
        detailName,
        isFirstInLesson: sIdx === 0,
        isLastInLesson: sIdx === subItemCount - 1,
        lessonRowCount: subItemCount,
        part1: rowP1,
        part2: rowP2,
        part3: rowP3,
        total: (rowP1.know + rowP1.understand) + (rowP2.know + rowP2.understand + rowP2.apply) + rowP3.apply
      });
    });
  });

  return {
    grade,
    chapter,
    rows,
    totals: {
      part1: { know: 12, understand: 6, apply: 0 },
      part2: { know: 4, understand: 6, apply: 6 },
      part3: { know: 0, understand: 0, apply: 6 },
      grandTotal: 40,
      ratio: { know: 16, understand: 12, apply: 12 }
    }
  };
};

