import { Grade, Chapter, MatrixData, MatrixRow, CognitiveLevel } from '../types';

export const generateMatrix = (grade: Grade, chapter: Chapter, extraReq?: string): MatrixData => {
  const lessonCount = chapter.lessons.length;
  const grandTotal = 40;

  // 1. Prepare Flat List of all sub-items
  const allSubItems: { lessonId: string; lessonName: string; detailName: string; isPart2Eligible: boolean }[] = [];
  chapter.lessons.forEach(l => {
    const subs = l.subItems && l.subItems.length > 0 ? l.subItems : ['(Nội dung chung)'];
    subs.forEach(s => {
      const forbidden = ["vị trí", "cấu tạo", "trạng thái tự nhiên", "vị trí", "cau tao", "trang thai tu nhien"];
      const isPart2Eligible = !forbidden.some(f => s.toLowerCase().includes(f));
      allSubItems.push({ lessonId: l.id, lessonName: l.name, detailName: s, isPart2Eligible });
    });
  });

  // 2. Select exactly 4 items for Part II (True/False - 4 questions)
  // Each selected item will host 1 full question (4 commands)
  const eligibleIndices = allSubItems.map((s, i) => s.isPart2Eligible ? i : -1).filter(i => i !== -1);
  const part2Selection: number[] = [];

  // Pick 4 indices, trying to spread across lessons
  if (eligibleIndices.length > 0) {
    for (let i = 0; i < 4; i++) {
      const pick = eligibleIndices[Math.floor(Math.random() * eligibleIndices.length)];
      part2Selection.push(pick);
    }
  }

  // 3. Quotas for Part 1 (18) and Part 3 (6)
  // Distribute these across all items to ensure coverage
  const distribute = (total: number, bins: number): number[] => {
    if (bins === 0) return [];
    const base = Math.floor(total / bins);
    const remainder = total % bins;
    return Array.from({ length: bins }, (_, i) => base + (i < remainder ? 1 : 0));
  };

  const p1k_dist = distribute(12, allSubItems.length);
  const p1u_dist = distribute(6, allSubItems.length);
  const p3v_dist = distribute(6, allSubItems.length);

  // Define Part 2 commands to allocate (Standard: 4 Know, 6 Understand, 6 Apply for the 4 questions)
  const p2k_pool = [1, 1, 1, 1]; // 4 questions, each gets 1 know? Or distribute 4 across 4.
  const p2u_pool = [2, 1, 2, 1]; // Total 6
  const p2v_pool = [1, 2, 1, 2]; // Total 6

  const rows: MatrixRow[] = allSubItems.map((item, idx) => {
    const isP2Host = part2Selection.includes(idx);
    const p2Occurrences = part2Selection.filter(i => i === idx).length;

    const rowP1 = { know: p1k_dist[idx], understand: p1u_dist[idx], apply: 0 };
    const rowP2 = { 
      know: isP2Host ? p2k_pool.slice(0, p2Occurrences).reduce((a, b) => a + b, 0) : 0, 
      understand: isP2Host ? p2u_pool.slice(0, p2Occurrences).reduce((a, b) => a + b, 0) : 0, 
      apply: isP2Host ? p2v_pool.slice(0, p2Occurrences).reduce((a, b) => a + b, 0) : 0 
    };
    const rowP3 = { know: 0, understand: 0, apply: p3v_dist[idx] };

    const lessonRows = allSubItems.filter(s => s.lessonId === item.lessonId);
    const lessonIdx = lessonRows.indexOf(item);

    return {
      content: chapter.name,
      lessonName: item.lessonName,
      detailName: item.detailName,
      isFirstInLesson: lessonIdx === 0,
      isLastInLesson: lessonIdx === lessonRows.length - 1,
      lessonRowCount: lessonRows.length,
      part1: rowP1,
      part2: rowP2,
      part3: rowP3,
      total: (rowP1.know + rowP1.understand) + (rowP2.know + rowP2.understand + rowP2.apply) + rowP3.apply
    };
  });

  return {
    grade,
    chapter,
    extraRequirements: extraReq,
    rows,
    totals: {
      part1: { know: 12, understand: 6, apply: 0 },
      part2: { know: 4, understand: 6, apply: 6 },
      part3: { know: 0, understand: 0, apply: 6 },
      grandTotal,
      ratio: { know: 16, understand: 12, apply: 12 }
    }
  };
};

