  const [activeGrade, setActiveGrade] = useState<Grade | null>(null);
  const [selectedChapter, setSelectedChapter] = useState<Chapter | null>(null);
  const [editableLessons, setEditableLessons] = useState<Lesson[]>([]);
  const [newLessonName, setNewLessonName] = useState('');
  const [extraRequirements, setExtraRequirements] = useState('');
  const [matrixData, setMatrixData] = useState<MatrixData | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [expandedLessonId, setExpandedLessonId] = useState<string | null>(null);

  useEffect(() => {
    if (selectedChapter) {
      setEditableLessons(selectedChapter.lessons.map(l => ({ ...l, subItems: l.subItems || [] })));
    } else {
      setEditableLessons([]);
    }
  }, [selectedChapter]);

  const handleGradeSelect = (grade: Grade) => {
    setActiveGrade(grade);
    setSelectedChapter(null);
    setMatrixData(null);
  };

  const handleCreateNew = () => {
    setActiveGrade(null);
    setSelectedChapter(null);
    setMatrixData(null);
    setEditableLessons([]);
    setExtraRequirements('');
  };

  const handleAddLesson = () => {
    if (!newLessonName.trim()) return;
    const newLesson: Lesson = {
      id: `custom_${Date.now()}`,
      name: newLessonName.trim(),
      subItems: []
    };
    setEditableLessons([...editableLessons, newLesson]);
    setNewLessonName('');
    setExpandedLessonId(newLesson.id);
  };

  const handleRemoveLesson = (id: string) => {
    setEditableLessons(editableLessons.filter(l => l.id !== id));
  };

  const handleAddSubItem = (lessonId: string, itemName: string) => {
    if (!itemName.trim()) return;
    setEditableLessons(prev => prev.map(l => {
      if (l.id === lessonId) {
        const currentItems = l.subItems || [];
        if (currentItems.length >= 5) return l; 
        return { ...l, subItems: [...currentItems, itemName.trim()] };
      }
      return l;
    }));
  };

  const handleRemoveSubItem = (lessonId: string, index: number) => {
    setEditableLessons(prev => prev.map(l => {
      if (l.id === lessonId) {
        return { ...l, subItems: (l.subItems || []).filter((_, i) => i !== index) };
      }
      return l;
    }));
  };

  const handleGenerate = () => {
    if (!activeGrade || !selectedChapter || editableLessons.length === 0) return;
    setIsGenerating(true);

    const customChapter: Chapter = {
      ...selectedChapter,
      lessons: editableLessons
    };

    setTimeout(() => {
      const data = generateMatrix(activeGrade, customChapter, extraRequirements);
      setMatrixData(data);
      setIsGenerating(false);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }, 800);
  };

  const exportToExcel = () => {
    if (!matrixData) return;
    const wsData = [
      ['MA TRẬN CHI TIẾT ĐỀ KIỂM TRA HÓA HỌC'],
      [`LỚP ${matrixData.grade} - ${matrixData.chapter.name}`],
      [],
      ['TT', 'Nội dung', 'Đơn vị', 'Chi tiết', 'P1-B', 'P1-H', 'P1-V', 'P2-B', 'P2-H', 'P2-V', 'P3-B', 'P3-H', 'P3-V', 'Tổng', 'Tỉ lệ'],
      ...matrixData.rows.map((row, idx) => [
        idx + 1, row.content, row.lessonName, row.detailName,
        row.part1.know, row.part1.understand, row.part1.apply,
        row.part2.know, row.part2.understand, row.part2.apply,
        row.part3.know, row.part3.understand, row.part3.apply,
        row.total, `${((row.total / 40) * 100).toFixed(1)}%`
      ]),
      [],
      ['Yêu cầu khác:', matrixData.extraRequirements || 'Không có']
    ];
    const ws = XLSX.utils.aoa_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Matrix');
    XLSX.writeFile(wb, `Matrix_Chemistry_Grade${matrixData.grade}.xlsx`);
  };

  const exportToImage = async () => {
    const element = document.getElementById('matrix-table-container');
    if (!element) return;
    const canvas = await html2canvas(element, { scale: 2 });
    const link = document.createElement('a');
    link.download = `Matrix_Chemistry_G${matrixData?.grade}.png`;
    link.href = canvas.toDataURL('image/png', 1.0);
    link.click();
  };

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col pb-16 font-sans">
      <header className="bg-gradient-to-r from-blue-900 via-indigo-900 to-slate-900 text-white p-6 shadow-2xl no-print">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-white/10 p-3 rounded-2xl backdrop-blur-md border border-white/20">
              <Layout className="w-8 h-8 text-amber-400" />
            </div>
            <div>
              <h1 className="text-2xl font-black uppercase tracking-tight italic">ChemMatrix <span className="text-amber-400">Pro</span></h1>
              <p className="text-indigo-200 text-[10px] font-bold uppercase tracking-[0.2em] opacity-80">Chương trình GDPT 2018 - Smart Engine</p>
            </div>
          </div>
          <button 
            onClick={handleCreateNew}
            className="bg-white/10 hover:bg-white/20 text-white px-6 py-2 rounded-full font-bold border border-white/20 transition-all flex items-center gap-2 text-sm uppercase"
          >
            <Plus className="w-4 h-4" /> Làm lại từ đầu
          </button>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full p-6 space-y-8">
        {!matrixData && (
          <div className="space-y-6 no-print">
            <div className="bg-white rounded-3xl shadow-xl p-10 border border-slate-200 overflow-hidden relative">
              <div className="absolute top-0 right-0 p-8 opacity-5"><School className="w-32 h-32" /></div>
              <h3 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-3">
                <span className="bg-blue-600 text-white w-10 h-10 rounded-2xl flex items-center justify-center text-sm">1</span>
                Lựa chọn phạm vi kiến thức
              </h3>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
                {[10, 11, 12].map((g) => (
                  <button
                    key={g}
                    onClick={() => handleGradeSelect(g as Grade)}
                    className={`relative overflow-hidden p-8 rounded-3xl border-4 transition-all text-left group ${
                      activeGrade === g 
                      ? 'border-blue-600 bg-blue-50/50 scale-[1.02] shadow-xl shadow-blue-100' 
                      : 'border-slate-50 bg-slate-50 hover:border-slate-200 hover:bg-white'
                    }`}
                  >
                    <span className={`text-5xl font-black mb-1 block tracking-tighter transition-colors ${activeGrade === g ? 'text-blue-700' : 'text-slate-300 group-hover:text-slate-400'}`}>LỚP {g}</span>
                    <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Hóa học phổ thông</span>
                  </button>
                ))}
              </div>

              {activeGrade && (
                <div className="animate-in fade-in slide-in-from-top-4 duration-500">
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 max-h-[400px] overflow-y-auto pr-3 custom-scrollbar">
                    {CURRICULUM[activeGrade].map((chapter) => (
                      <button
                        key={chapter.id}
                        onClick={() => setSelectedChapter(chapter)}
                        className={`p-5 text-left rounded-2xl border-2 transition-all text-sm font-bold leading-snug ${
                          selectedChapter?.id === chapter.id
                          ? 'bg-indigo-600 text-white border-indigo-600 shadow-xl shadow-indigo-100'
                          : 'bg-white text-slate-600 border-slate-100 hover:border-indigo-200 hover:text-indigo-600'
                        }`}
                      >
                        {chapter.name}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {selectedChapter && (
              <div className="bg-white rounded-3xl shadow-xl p-10 border border-slate-200 animate-in fade-in zoom-in-95 duration-500">
                <h3 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-3">
                  <span className="bg-indigo-600 text-white w-10 h-10 rounded-2xl flex items-center justify-center text-sm">2</span>
                  Bổ sung mục chi tiết & Yêu cầu
                </h3>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-10">
                  <div className="lg:col-span-2 space-y-4">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                      <ListFilter className="w-3 h-3" /> Danh sách đơn vị kiến thức
                    </p>
                    {editableLessons.map((lesson, idx) => (
                      <div key={lesson.id} className="border-2 rounded-2xl overflow-hidden bg-slate-50/50 border-slate-100 transition-all hover:border-indigo-100">
                        <div 
                          className="flex items-center justify-between p-5 bg-white cursor-pointer group"
                          onClick={() => setExpandedLessonId(expandedLessonId === lesson.id ? null : lesson.id)}
                        >
                          <div className="flex items-center gap-4">
                            <span className="bg-slate-100 text-slate-400 group-hover:bg-indigo-600 group-hover:text-white w-8 h-8 rounded-xl flex items-center justify-center text-xs font-black transition-colors">
                              {idx + 1}
                            </span>
                            <div>
                              <span className="font-bold text-slate-800 text-base">{lesson.name}</span>
                              <div className="flex gap-1 mt-1">
                                {(lesson.subItems || []).length > 0 ? (
                                  (lesson.subItems || []).map((_, i) => <div key={i} className="w-3 h-1 bg-green-400 rounded-full"></div>)
                                ) : (
                                  <span className="text-[9px] text-slate-400 font-bold uppercase italic">Chưa chia nhỏ nội dung</span>
                                )}
                              </div>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <button 
                              onClick={(e) => { e.stopPropagation(); handleRemoveLesson(lesson.id); }}
                              className="p-2 text-slate-300 hover:text-red-500 transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                            {expandedLessonId === lesson.id ? <ChevronUp className="text-indigo-600 w-5 h-5" /> : <ChevronDown className="text-slate-400 w-5 h-5" />}
                          </div>
                        </div>

                        {expandedLessonId === lesson.id && (
                          <div className="p-6 bg-slate-50/50 border-t border-slate-100 space-y-4">
                            <div className="grid grid-cols-1 gap-2">
                              {(lesson.subItems || []).map((item, i) => (
                                <div key={i} className="flex items-center justify-between bg-white px-4 py-3 rounded-xl border border-slate-200 shadow-sm">
                                  <span className="text-sm font-medium text-slate-600 italic">Mục {i+1}: {item}</span>
                                  <button onClick={() => handleRemoveSubItem(lesson.id, i)} className="text-slate-300 hover:text-red-400">
                                    <Trash2 className="w-4 h-4" />
                                  </button>
                                </div>
                              ))}
                            </div>
                            {(lesson.subItems || []).length < 5 && (
                              <div className="flex gap-2">
                                <input 
                                  id={`input-${lesson.id}`}
                                  type="text" 
                                  placeholder="Nhập mục chi tiết..."
                                  className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                                  onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                      handleAddSubItem(lesson.id, (e.target as HTMLInputElement).value);
                                      (e.target as HTMLInputElement).value = '';
                                    }
                                  }}
                                />
                                <button 
                                  onClick={() => {
                                    const input = document.getElementById(`input-${lesson.id}`) as HTMLInputElement;
                                    handleAddSubItem(lesson.id, input.value);
                                    input.value = '';
                                  }}
                                  className="bg-indigo-600 text-white px-5 rounded-xl font-bold hover:bg-indigo-700 transition-colors"
                                >
                                  THÊM
                                </button>
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    ))}
                    <div className="flex gap-2 pt-4">
                      <input 
                        type="text"
                        value={newLessonName}
                        onChange={(e) => setNewLessonName(e.target.value)}
                        placeholder="Thêm đơn vị kiến thức khác..."
                        className="flex-1 p-4 border border-blue-100 rounded-2xl bg-blue-50/30 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                      <button onClick={handleAddLesson} className="bg-blue-600 text-white px-8 rounded-2xl font-bold hover:bg-blue-700">MỚI</button>
                    </div>
                  </div>

                  <div className="bg-slate-50 rounded-3xl p-6 border-2 border-slate-100 flex flex-col gap-4">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                      <MessageSquareQuote className="w-3 h-3 text-amber-500" /> Tùy chọn yêu cầu khác
                    </p>
                    <textarea 
                      value={extraRequirements}
                      onChange={(e) => setExtraRequirements(e.target.value)}
                      placeholder="VD: Ưu tiên phần bài tập tính chất hóa học, giảm nhẹ phần lý thuyết trạng thái tự nhiên..."
                      className="w-full h-full min-h-[150px] p-4 rounded-2xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-amber-400 resize-none italic bg-white"
                    />
                    <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100">
                      <p className="text-[10px] text-amber-700 leading-relaxed font-medium">
                        * Thông tin này sẽ được in trực tiếp vào ma trận để căn chỉnh nội dung bám sát yêu cầu thực tế của chương học.
                      </p>
                    </div>
                  </div>
                </div>

                <div className="flex justify-center mt-6">
                  <button
                    disabled={editableLessons.length === 0 || isGenerating}
                    onClick={handleGenerate}
                    className={`w-full max-w-md py-5 rounded-3xl font-black text-xl shadow-2xl transition-all flex items-center justify-center gap-4 ${
                      editableLessons.length === 0 || isGenerating
                      ? 'bg-slate-300 cursor-not-allowed text-slate-500'
                      : 'bg-gradient-to-r from-blue-700 to-indigo-800 text-white hover:scale-[1.03] active:scale-95'
                    }`}
                  >
                    {isGenerating ? 'ĐANG XỬ LÝ...' : 'XUẤT MA TRẬN CHI TIẾT'}
                    {!isGenerating && <Save className="w-7 h-7" />}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {matrixData && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="flex flex-col md:flex-row items-center justify-between gap-6 bg-white p-8 rounded-3xl border border-slate-200 shadow-xl no-print">
              <div className="flex items-center gap-4">
                <div className="bg-green-100 text-green-600 p-4 rounded-2xl"><CheckCircle className="w-8 h-8" /></div>
                <div>
                  <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight leading-none">Hoàn tất!</h3>
                  <p className="text-slate-500 text-sm mt-1">Ma trận đã được tạo dựa trên <b>{matrixData.rows.length}</b> mục nội dung và yêu cầu riêng.</p>
                </div>
              </div>
              <div className="flex flex-wrap gap-4 justify-center">
                <button onClick={exportToExcel} className="flex items-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-2xl font-black text-sm hover:bg-emerald-700 shadow-lg transition-all">
                  <FileSpreadsheet className="w-5 h-5" /> EXCEL
                </button>
                <button onClick={exportToImage} className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-lg transition-all">
                  <ImageIcon className="w-5 h-5" /> HÌNH ẢNH
                </button>
                <button onClick={() => window.print()} className="flex items-center gap-2 px-6 py-3 bg-slate-800 text-white rounded-2xl font-black text-sm hover:bg-black shadow-lg transition-all">
                  <Download className="w-5 h-5" /> XUẤT PDF
                </button>
              </div>
            </div>

            <MatrixDisplay data={matrixData} />
          </div>
        )}
      </main>

      <footer className="bg-white border-t p-10 mt-auto no-print">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6 text-slate-400 text-[10px] font-black uppercase tracking-[0.3em]">
          <p>© 2025 ChemMatrix Pro • Smart Matrix Generator</p>
          <div className="flex gap-8">
            <span className="hover:text-blue-600 cursor-pointer transition-colors">GDPT 2018 Standard</span>
            <span className="hover:text-blue-600 cursor-pointer transition-colors">Chemistry Department</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

export type Grade = 10 | 11 | 12;

export interface Lesson {
  id: string;
  name: string;
  subItems?: string[]; 
  part2Hosts?: string[]; // IDs or names of sub-items selected for Part II
}

export interface Chapter {
  id: string;
  name: string;
  lessons: Lesson[];
}

export interface CognitiveLevel {
  know: number;
  understand: number;
  apply: number;
}

export interface MatrixRow {
  content: string;
  lessonName: string;
  detailName: string; 
  isFirstInLesson: boolean; 
  isLastInLesson: boolean; 
  lessonRowCount: number; 
  part1: CognitiveLevel;
  part2: CognitiveLevel;
  part3: CognitiveLevel;
  total: number;
}

export interface MatrixData {
  grade: Grade;
  chapter: Chapter;
  extraRequirements?: string;
  rows: MatrixRow[];
  totals: {
    part1: CognitiveLevel;
    part2: CognitiveLevel;
    part3: CognitiveLevel;
    grandTotal: number;
    ratio: CognitiveLevel;
  };
}

import { Grade, Chapter, MatrixData, MatrixRow, CognitiveLevel } from '../types';

export const generateMatrix = (grade: Grade, chapter: Chapter, extraReq?: string): MatrixData => {
  const lessonCount = chapter.lessons.length;
  const grandTotal = 40;

  // 1. Fixed Part II Cognitive Distribution (16 commands total across 4 questions)
  // Q1: 4 Know, Q2: 4 Understand, Q3: 4 Understand, Q4: 4 Apply
  const p2QuestionQuotas = [
    { know: 4, understand: 0, apply: 0 }, // Q1
    { know: 0, understand: 4, apply: 0 }, // Q2
    { know: 0, understand: 4, apply: 0 }, // Q3
    { know: 0, understand: 0, apply: 4 }  // Q4
  ];

  // 2. Map all sub-items and identify Part II Hosts
  const allSubItems: { 
    lessonId: string; 
    lessonName: string; 
    detailName: string; 
    isP2Host: boolean;
    p2Quota: CognitiveLevel;
  }[] = [];

  let p2Counter = 0;
  chapter.lessons.forEach(l => {
    const subs = l.subItems && l.subItems.length > 0 ? l.subItems : ['(Nội dung chung)'];
    subs.forEach(s => {
      const isP2Host = l.part2Hosts?.includes(s) || false;
      const p2Quota = (isP2Host && p2Counter < 4) 
        ? p2QuestionQuotas[p2Counter++] 
        : { know: 0, understand: 0, apply: 0 };

      allSubItems.push({ lessonId: l.id, lessonName: l.name, detailName: s, isP2Host, p2Quota });
    });
  });

  // 3. Define Total Quotas needed to reach 40% Know, 30% Understand, 30% Apply
  // Total: 16 Know, 12 Understand, 12 Apply
  // Part II already uses: 4 Know, 8 Understand, 4 Apply
  // Remaining needed from Part I (MCQ) and Part III (SA):
  // Know: 12 (Part 1)
  // Understand: 4 (Part 1)
  // Apply: 12 (Part 1: 2 + Part 3: 6 + Part 1: 4?)
  // Let's optimize: 
  // Part I (18): 12 Know, 4 Understand, 2 Apply
  // Part III (6): 6 Apply

  const nonP2Items = allSubItems.filter(item => !item.isP2Host);
  const nonP2Count = nonP2Items.length;

  const distribute = (total: number, bins: number): number[] => {
    if (bins === 0) return [];
    const base = Math.floor(total / bins);
    const remainder = total % bins;
    return Array.from({ length: bins }, (_, i) => base + (i < remainder ? 1 : 0));
  };

  // Distribute Part I and Part III among non-P2 items
  const p1k_dist = distribute(12, nonP2Count);
  const p1u_dist = distribute(4, nonP2Count);
  const p1v_dist = distribute(2, nonP2Count);
  const p3v_dist = distribute(6, nonP2Count);

  let nonP2Idx = 0;
  const rows: MatrixRow[] = allSubItems.map((item) => {
    let rowP1 = { know: 0, understand: 0, apply: 0 };
    let rowP3 = { know: 0, understand: 0, apply: 0 };

    if (!item.isP2Host) {
      rowP1 = { know: p1k_dist[nonP2Idx], understand: p1u_dist[nonP2Idx], apply: p1v_dist[nonP2Idx] };
      rowP3 = { know: 0, understand: 0, apply: p3v_dist[nonP2Idx] };
      nonP2Idx++;
    }

    const lessonRows = allSubItems.filter(s => s.lessonId === item.lessonId);
    const itemIdxInLesson = lessonRows.indexOf(item);

    return {
      content: chapter.name,
      lessonName: item.lessonName,
      detailName: item.detailName,
      isFirstInLesson: itemIdxInLesson === 0,
      isLastInLesson: itemIdxInLesson === lessonRows.length - 1,
      lessonRowCount: lessonRows.length,
      part1: rowP1,
      part2: item.p2Quota,
      part3: rowP3,
      total: (rowP1.know + rowP1.understand + rowP1.apply) + (item.p2Quota.know + item.p2Quota.understand + item.p2Quota.apply) + rowP3.apply
    };
  });

  return {
    grade,
    chapter,
    extraRequirements: extraReq,
    rows,
    totals: {
      part1: { know: 12, understand: 4, apply: 2 },
      part2: { know: 4, understand: 8, apply: 4 },
      part3: { know: 0, understand: 0, apply: 6 },
      grandTotal: 40,
      ratio: { know: 16, understand: 12, apply: 12 }
    }
  };
};

import React, { useState, useEffect } from 'react';
import { CURRICULUM } from './constants';
import { Grade, Chapter, MatrixData, Lesson } from './types';
import { generateMatrix } from './services/matrixService';
import MatrixDisplay from './components/MatrixDisplay';
import { 
  Layout, Plus, Download, FileSpreadsheet, Image as ImageIcon, 
  CheckCircle, School, Trash2, Save, 
  ChevronDown, ChevronUp, ListFilter, MessageSquareQuote,
  Target, AlertTriangle
} from 'lucide-react';
import * as XLSX from 'xlsx';
import html2canvas from 'html2canvas';

const App: React.FC = () => {
  const [activeGrade, setActiveGrade] = useState<Grade | null>(null);
  const [selectedChapter, setSelectedChapter] = useState<Chapter | null>(null);
  const [editableLessons, setEditableLessons] = useState<Lesson[]>([]);
  const [newLessonName, setNewLessonName] = useState('');
  const [extraRequirements, setExtraRequirements] = useState('');
  const [matrixData, setMatrixData] = useState<MatrixData | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [expandedLessonId, setExpandedLessonId] = useState<string | null>(null);

  useEffect(() => {
    if (selectedChapter) {
      setEditableLessons(selectedChapter.lessons.map(l => ({ ...l, subItems: l.subItems || [], part2Hosts: [] })));
    } else {
      setEditableLessons([]);
    }
  }, [selectedChapter]);

